import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { depsHash, pathPackages, pruneList, rustcSlug } from "./cargo-cache.mjs";

const LOCK = `# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "anyhow"
version = "1.0.99"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "aaaa"

[[package]]
name = "ps5upload-core"
version = "12.6.2"
dependencies = [
 "anyhow",
]

[[package]]
name = "unrar"
version = "0.5.8"
dependencies = [
 "anyhow",
]
`;

test("path packages are the ones without a source", () => {
  assert.deepEqual(pathPackages(LOCK), ["ps5upload-core", "unrar"]);
});

test("a release bump keeps the key; a dependency change makes a new one", () => {
  const bumped = LOCK.replace('version = "12.6.2"', 'version = "12.6.3"');
  assert.equal(depsHash([bumped]), depsHash([LOCK]));
  assert.equal(depsHash([LOCK.replace(/\n/g, "\r\n")]), depsHash([LOCK]));
  const dep = LOCK.replace('version = "1.0.99"', 'version = "1.0.100"');
  assert.notEqual(depsHash([dep]), depsHash([LOCK]));
  // Two lockfiles are not the same as one.
  assert.notEqual(depsHash([LOCK, LOCK]), depsHash([LOCK]));
});

test("the repository's own lockfiles parse", () => {
  const engine = pathPackages(readFileSync("engine/Cargo.lock", "utf8"));
  assert.ok(engine.includes("ps5upload-engine") && engine.includes("ps5upload-tests"), engine.join(" "));
  assert.ok(!engine.includes("anyhow"));
  const desktop = pathPackages(readFileSync("client/src-tauri/Cargo.lock", "utf8"));
  assert.ok(desktop.includes("ps5upload-desktop"), desktop.join(" "));
});

test("rustc version slug", () => {
  assert.equal(rustcSlug("rustc 1.100.0 (58cf8f9c3 2026-10-13)"), "rust1.100.0-58cf8f9c3");
  assert.equal(rustcSlug("rustc 1.101.0-nightly (abc123def 2026-11-01)"), "rust1.101.0-nightly-abc123def");
  assert.throws(() => rustcSlug("cargo 1.100.0"));
});

test("prune takes our crates' output and leaves the dependencies", () => {
  const t = mkdtempSync(join(tmpdir(), "cargo-cache-"));
  try {
    const mk = (p, dir = false) => {
      const full = join(t, p);
      mkdirSync(dir ? full : join(full, ".."), { recursive: true });
      if (!dir) writeFileSync(full, "x");
    };
    // Rust >= 1.100 layout
    mk("debug/build/anyhow/0123456789abcdef/out/x");
    mk("debug/build/ps5upload-core/0123456789abcdef/out/test-bin");
    mk("debug/build/unrar/fedcba9876543210/out/x");
    // older layout, and a cross target
    mk("aarch64-linux-android/debug/deps/libanyhow-0123456789abcdef.rlib");
    mk("aarch64-linux-android/debug/deps/libps5upload_core-0123456789abcdef.rlib");
    mk("aarch64-linux-android/debug/deps/ps5upload_core-0123456789abcdef.d");
    mk("aarch64-linux-android/debug/.fingerprint/ps5upload-core-0123456789abcdef/x");
    mk("aarch64-linux-android/debug/.fingerprint/anyhow-0123456789abcdef/x");
    mk("debug/libps5upload_core.rlib");
    mk("debug/ps5upload-core.exe");
    mk("debug/examples", true);
    mk("tmp/huge.img");
    const got = pruneList(t, ["ps5upload-core", "unrar"]).map((p) => p.slice(t.length + 1).replace(/\\/g, "/")).sort();
    assert.deepEqual(got, [
      "aarch64-linux-android/debug/.fingerprint/ps5upload-core-0123456789abcdef",
      "aarch64-linux-android/debug/deps/libps5upload_core-0123456789abcdef.rlib",
      "aarch64-linux-android/debug/deps/ps5upload_core-0123456789abcdef.d",
      "debug/build/ps5upload-core",
      "debug/build/unrar",
      "debug/examples",
      "debug/libps5upload_core.rlib",
      "debug/ps5upload-core.exe",
      "tmp",
    ]);
  } finally {
    rmSync(t, { recursive: true, force: true });
  }
});
